// Finite State Machine to detect the start of a PS/2 mouse message
// (three-byte boundary) within a byte stream.
module TopModule(
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg done
);
    reg [1:0] state, next_state;
    reg [7:0] bytes [0:2];
    reg [1:0] byte_count;
    reg [7:0] data;
    reg [7:0] parity;
    wire valid = (byte_count == 2) && (parity == data[7]);

    always @(*) begin
        next_state = state;
        case (state)
            2'd0: if (in[3]) next_state = 2'd1;
            2'd1: if (byte_count == 2) next_state = 2'd2;
            2'd2: begin
                if (valid) next_state = 2'd0;
                else next_state = 2'd1;
            end
        endcase
