// State 0 is unused, the first state is 1, the last is 8, so there are 8
// states in total.
localparam STATE_1 = 1;
localparam STATE_2 = 2;
localparam STATE_3 = 4;

module TopModule(
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg done
);
    reg [2:0] state;
    reg [7:0] bytes [0:2];
    reg [2:0] byte_index;

    always @(posedge clk) begin
        if (reset) begin
            state <= STATE_1;
            byte_index <= 0;
            done <= 0;
        end else begin
            case (state)
                STATE_1: begin
                    if (in[3] == 1) begin
                        bytes[0] <= in;
                        byte_index <= 1;
                        state <= STATE_2;
                    end
                end
                STATE_2: begin
                    bytes[byte_index] <= in;
                    byte_index <= byte_index + 1;
                    if (byte_index == 3) begin
                        state <= STATE_3;
                    end
                end
                STATE_3: begin
                    done <= 1;
                    state <= STATE_1;
                end
            endcase
        end
    end
endmodule

