// One-bit finite state machine. The combinational multiplexer selects the
// next state based on the current state and the input. The output done is
// a pulse that goes high for one clock cycle when byte 3 of a message is
// received.
module TopModule(input clk, input reset, input [7:0] in, output reg done);
  reg [1:0] state;
  reg [2:0] count;
  always @(posedge clk) begin
    if (reset) begin
      state <= 2'b00;
      count <= 3'b000;
      done <= 1'b0;
    end else begin
      case (state)
        2'b00: begin // Wait for first byte with in[3]=1
          if (in[3]) begin
            state <= 2'b01;
            count <= 3'b001;
          end
        end
        2'b01: begin // Wait for second byte with in[3]=0
          if (!in[3]) begin
            state <= 2'b10;
            count <= 3'b010;
          end
        end
        2'b10: begin // Wait for third byte
          if (count == 3'b011) begin
            done <= 1'b1;
          end
          state <= 2'b00;
          count <= 3'b000;
        end
      endcase
      count <= count + 1;
    end
  end
endmodule

