// - State 0: Wait for the first byte of a message.
// - State 1: Wait for the second byte of a message.
// - State 2: Wait for the third and final byte of a message.
// - Once a message is completely received (done goes high), the FSM
//   goes back to state 0 and waits for the next message.
// - Resetting the FSM goes back to state 0.
module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg done
);
    reg [1:0] state;
    reg [7:0] bytes [0:2];
    reg [2:0] byte_idx;
    always @(posedge clk) begin
        if (reset) begin
            state <= 0;
            byte_idx <= 0;
            done <= 0;
        end else begin
            case (state)
                0: begin
                    if (in[3] == 1) begin
                        bytes[0] <= in;
                        byte_idx <= 1;
                        state <= 1;
                    end
                end
                1: begin
                    bytes[1] <= in;
                    byte_idx <= 2;
                    state <= 2;
                end
                2: begin
                    bytes[2] <= in;
                    done <= 1;
                    state <= 0;
                end
            endcase
        end
    end
endmodule

