// Finite State Machine
// Search for message boundaries in a continuous byte stream.
// The algorithm is to discard bytes until we see one with in[3]=1.
// Then we assume that this is byte 1 of a message, and signal the receipt
// of a message once all 3 bytes have been received (done). The FSM signals
// done in the cycle immediately after the third byte of each message was
// successfully received.
module TopModule (
  input  clk,
  input  reset,
  input  [7:0] in,
  output reg done
);
  reg [1:0] state;
  reg [7:0] bytes [0:2];
  reg [2:0] byte_count;
  always @(posedge clk) begin
    if (reset) begin
      state <= 2'b00;
      byte_count <= 3'b000;
      done <= 1'b0;
    end else begin
      case (state)
        2'b00: begin // Wait for first byte with in[3]=1
          if (in[3]) begin
            state <= 2'b01;
            bytes[0] <= in;
            byte_count <= 3'b001;
