        end
        2'b01: begin // Wait for second byte
          bytes[1] <= in;
          byte_count <= 3'b010;
          state <= 2'b10;
        end
        2'b10: begin // Wait for third byte
          bytes[2] <= in;
          byte_count <= 3'b011;
          state <= 2'b00;
          done <= 1'b1;
        end
      endcase
    end
  end
endmodule

